CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.' || :silver_schema || '.dim_city') AS
WITH cities AS (
  SELECT CityID, CityName, StateProvinceID, Location, LatestRecordedPopulation, ValidFrom, ValidTo
  FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.cities')
  UNION ALL
  SELECT CityID, CityName, StateProvinceID, Location, LatestRecordedPopulation, ValidFrom, ValidTo
  FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.cities_archive')
),
states AS (
  SELECT StateProvinceID, StateProvinceName, CountryID, SalesTerritory, ValidFrom, ValidTo
  FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.stateprovinces')
  UNION ALL
  SELECT StateProvinceID, StateProvinceName, CountryID, SalesTerritory, ValidFrom, ValidTo
  FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.stateprovinces_archive')
),
countries AS (
  SELECT CountryID, CountryName, Continent, Region, Subregion, ValidFrom, ValidTo
  FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.countries')
  UNION ALL
  SELECT CountryID, CountryName, Continent, Region, Subregion, ValidFrom, ValidTo
  FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.countries_archive')
),
events AS (
  SELECT 'country' AS scope, CountryID AS entity_id, ValidFrom AS valid_from FROM countries
  WHERE ValidFrom <> '2013-01-01 00:00:00.0000000'
  UNION ALL
  SELECT 'state', StateProvinceID, ValidFrom FROM states
  WHERE ValidFrom <> '2013-01-01 00:00:00.0000000'
  UNION ALL
  SELECT 'city', CityID, ValidFrom FROM cities
),
staged AS (
  SELECT c.CityID AS wwi_city_id, c.CityName AS city, s.StateProvinceName AS state_province,
         co.CountryName AS country, co.Continent AS continent, s.SalesTerritory AS sales_territory,
         co.Region AS region, co.Subregion AS subregion, c.Location AS location,
         COALESCE(c.LatestRecordedPopulation, 0) AS latest_recorded_population,
         e.valid_from,
         ROW_NUMBER() OVER (
           PARTITION BY c.CityID, e.valid_from ORDER BY e.scope, e.entity_id
         ) AS occurrence
  FROM events e
  INNER JOIN cities c ON c.ValidFrom <= e.valid_from AND e.valid_from < c.ValidTo
  INNER JOIN states s ON s.StateProvinceID = c.StateProvinceID
                     AND s.ValidFrom <= e.valid_from AND e.valid_from < s.ValidTo
  INNER JOIN countries co ON co.CountryID = s.CountryID
                         AND co.ValidFrom <= e.valid_from AND e.valid_from < co.ValidTo
  WHERE e.valid_from > '2012-12-31 00:00:00.0000000'
    AND e.valid_from <= '2016-06-06 12:31:17.0000000'
    AND ((e.scope = 'country' AND co.CountryID = e.entity_id)
      OR (e.scope = 'state' AND s.StateProvinceID = e.entity_id)
      OR (e.scope = 'city' AND c.CityID = e.entity_id))
),
version_times AS (
  SELECT wwi_city_id, valid_from FROM staged GROUP BY wwi_city_id, valid_from
),
validity AS (
  SELECT wwi_city_id, valid_from,
         COALESCE(LEAD(valid_from) OVER (PARTITION BY wwi_city_id ORDER BY valid_from),
                  '9999-12-31 23:59:59.9999999') AS valid_to
  FROM version_times
),
