       CAST(s.sales_territory AS STRING) AS sales_territory,
       CAST(s.region AS STRING) AS region,
       CAST(s.subregion AS STRING) AS subregion,
       CAST(s.location AS STRING) AS location,
       CAST(s.latest_recorded_population AS BIGINT) AS latest_recorded_population,
       CAST(s.valid_from AS STRING) AS valid_from,
       CAST(v.valid_to AS STRING) AS valid_to,
       CAST(1 AS INT) AS lineage_key
FROM staged s
INNER JOIN validity v ON v.wwi_city_id = s.wwi_city_id AND v.valid_from = s.valid_from
INNER JOIN allocations a ON a.wwi_city_id = s.wwi_city_id AND a.valid_from = s.valid_from
                        AND a.occurrence = s.occurrence
UNION ALL
SELECT CAST(0 AS INT), CAST(0 AS INT), CAST('Unknown' AS STRING),
       CAST('N/A' AS STRING), CAST('N/A' AS STRING), CAST('N/A' AS STRING),
       CAST('N/A' AS STRING), CAST('N/A' AS STRING), CAST('N/A' AS STRING),
       CAST(NULL AS STRING), CAST(0 AS BIGINT),
       CAST('2013-01-01 00:00:00.0000000' AS STRING),
       CAST('9999-12-31 23:59:59.9999999' AS STRING), CAST(0 AS INT);
